<?php
require_once __DIR__.'/includes/portal.php';$db=portalDb();$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{
    portalCsrf();$username=cbText($_POST['username']??'',50);$name=cbText($_POST['full_name']??'');$email=cbText($_POST['email']??'',190);$department=cbDepartment($_POST['department']??'');$password=(string)($_POST['password']??'');
    cbPassword($password,(string)($_POST['confirm_password']??''));
    if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Use a valid institutional email.');
    $db->beginTransaction();$employee=cbNextAccountId($db,'professor');cbUniqueIdentifiers($db,'professor',['username'=>$username,'employee_id'=>$employee,'email'=>$email]);cbQuery($db,'INSERT INTO professors(employee_id,username,full_name,email,department,password_hash) VALUES(?,?,?,?,?,?)',[$employee,$username,$name,$email,$department,password_hash($password,PASSWORD_DEFAULT)]);$id=(int)$db->lastInsertId();cbStoreAccountId($db,'professor',$id,$employee);
    cbQuery($db,"INSERT INTO classbook_access(role,account_id,status) VALUES('professor',?,'pending')",[$id]);cbAudit($db,['role'=>'guest','id'=>0],null,'faculty_requested',['account_id'=>$id]);$db->commit();portalRedirect('index.php','Request received. The Registrar must verify and approve your faculty account before you can sign in.');
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=portalError($e);}
portalStart('Faculty account request');portalHeading('Request faculty access','Your professor ID is generated automatically. Your class record becomes available after account verification.');if($error)portalNotice($error,'danger');?><section class="card narrow"><form method="post"><?=csrfField()?><?php portalField('Username','username','','text','required maxlength="50"');portalField('Full name','full_name','','text','required');portalField('Institutional email','email','','email','required');portalSelect('Department','department',[''=>'Choose department']+CB_DEPARTMENTS,'','required');portalField('Password','password','','password','required minlength="12" autocomplete="new-password"');portalField('Confirm password','confirm_password','','password','required minlength="12" autocomplete="new-password"');?><button>Submit request</button></form></section><?php portalEnd();
